import { generateHuffmanTable } from '../../../src/core/flate_stream';

describe('generateHuffmanTable', () => {
  it('should handle empty input', () => {
    const lengths = [];
    const [codes, maxLen] = generateHuffmanTable(lengths);

    expect(maxLen).toBe(0);
    expect(codes).toBeInstanceOf(Int32Array);
    expect(codes.length).toBe(1 << 0);
  });

  it('should handle single symbol', () => {
    const lengths = [1];
    const [codes, maxLen] = generateHuffmanTable(lengths);

    expect(maxLen).toBe(1);
    expect(codes.length).toBe(2);
    // For len=1, code=0, val=0. Bit reversed code is 0.
    // Entry at index 0 should store (1 << 16) | 0.
    expect(codes[0]).toBe((1 << 16) | 0);
    expect(codes[1]).toBe(0);
  });

  it('should handle a simple sequence of increasing code lengths', () => {
    const lengths = [1, 2, 2];
    const [codes, maxLen] = generateHuffmanTable(lengths);

    expect(maxLen).toBe(2);
    expect(codes.length).toBe(4);

    // val 0: len 1. code=0. reversed=0. skip=2. indices: 0.
    // Entry: (1 << 16) | 0
    expect(codes[0]).toBe((1 << 16) | 0);

    // val 1: len 2. code=0. reversed=0. skip=4. indices: 0.
    // Entry: (2 << 16) | 1
    expect(codes[0]).toBe((2 << 16) | 1);

    // val 2: len 2. code=1. reversed=2 (10b). skip=4. indices: 2.
    // Entry: (2 << 16) | 2
    expect(codes[2]).toBe((2 << 16) | 2);
  });

  it('should handle zero-length codes', () => {
    const lengths = [0, 0, 2];
    const [codes, maxLen] = generateHuffmanTable(lengths);

    expect(maxLen).toBe(2);
    expect(codes.length).toBe(4);

    // Only val 2 (len 2, code 0) should be written
    expect(codes[0]).toBe((2 << 16) | 2);
    expect(codes[1]).toBe(0);
    expect(codes[2]).toBe(0);
    expect(codes[3]).toBe(0);
  });

  it('should handle a complex distribution', () => {
    // Example distribution often seen in deflate specs
    const lengths = [2, 1, 3, 3];
    const [codes, maxLen] = generateHuffmanTable(lengths);

    expect(maxLen).toBe(3);
    expect(codes.length).toBe(8);

    // val 1: len 1. code=0. rev=0. skip=2. indices: 0, 2, 4, 6.
    // Entry: (1 << 16) | 1
    expect(codes[0]).toBe((1 << 16) | 1);
    expect(codes[2]).toBe((1 << 16) | 1);
    expect(codes[4]).toBe((1 << 16) | 1);
    expect(codes[6]).toBe((1 << 16) | 1);

    // val 0: len 2. code=0. rev=0. skip=4. indices: 0, 4.
    // Entry: (2 << 16) | 0
    expect(codes[0]).toBe((2 << 16) | 0);
    expect(codes[4]).toBe((2 << 16) | 0);

    // val 2: len 3. code=0. rev=0. skip=8. indices: 0.
    // Entry: (3 << 16) | 2
    expect(codes[0]).toBe((3 << 16) | 2);

    // val 3: len 3. code=1. rev=4 (100b). skip=8. indices: 4.
    // Entry: (3 << 16) | 3
    expect(codes[4]).toBe((3 << 16) | 3);
  });

  it('should handle non-sequential lengths', () => {
    const lengths = [3, 3, 3, 3, 3, 2, 4, 4];
    const [codes, maxLen] = generateHuffmanTable(lengths);

    expect(maxLen).toBe(4);
    expect(codes.length).toBe(16);

    // Check a specific known value for this configuration (val 5, len 2)
    // It should occupy every 4th entry starting at 0.
    // val 5 is the 6th element (index 5).
    // len 2 starts at code 0.
    // Expected value: (2 << 16) | 5
    expect(codes[0]).toBe((2 << 16) | 5);
    expect(codes[4]).toBe((2 << 16) | 5);
  });
});

